public class ObfuscatedTO implements Serializable {
    private static final long serialVersionUID = 1L;
    private final Map<String, Object> plain = new LinkedHashMap<>();
    private final Map<String, Object> protectedPairs = new LinkedHashMap<>();
    private SealedObject sealed;                                  // JCE
    public void seal(Cipher cipher) throws Exception {
        sealed = new SealedObject(new HashMap<>(protectedPairs), cipher);
        protectedPairs.clear();                                   // drop the plaintext copy
    }
    public Map<String, Object> unseal(Cipher cipher) throws Exception {
        return (Map<String, Object>) sealed.getObject(cipher);    // wrong key -> exception
    }
    @Override public String toString() { return "ObfuscatedTO" + plain.keySet(); }
}

