public class ObfuscatedTO implements Serializable {
    private static final Set<String> PROTECTED = Set.of("cardNumber", "ssn");
    private final Map<String, Object> plain = new LinkedHashMap<>();
    private final Map<String, Object> masked = new LinkedHashMap<>();

    public void set(String name, Object value) {
        (PROTECTED.contains(name) ? masked : plain).put(name, value);
    }
    public Object get(String name) {                    // explicit access, never printed
        return PROTECTED.contains(name) ? masked.get(name) : plain.get(name);
    }
    @Override public String toString() { return "ObfuscatedTO" + plain; }   // masked omitted
}
